<?php
use App\Services\{StudentService as S,TranslationService};
$courses=S::courses($student);$lang=TranslationService::currentCode();page_header('Downloads'); ?>
<section class="card"><h2><?= e(tr('Learn anywhere')) ?></h2><p class="muted"><?= e(tr('Download unlocked lessons while online. Downloaded text and media can be opened offline on this device.')) ?></p><p class="status-note" data-storage-info></p><a class="btn" href="sync_status.php"><?= e(tr('Sync status')) ?></a></section>
<form data-student-downloads data-owner="<?= $student ?>">
